android.extraProguardRules:
# Google Navigation SDK e a ponte React Native (usam reflexão e JNI)
-keep class com.google.android.react.navsdk.** { *; }
-keep class com.google.android.libraries.navigation.** { *; }
-keep class com.google.android.libraries.mapsplatform.** { *; }
# Tela do Android Auto do app (declarada no manifesto e chamada pelo carro)
-keep class com.bodesdoasfalto.app.auto.** { *; }
-keep class androidx.car.app.** { *; }
# MapLibre (JNI)
-keep class org.maplibre.** { *; }
-dontwarn com.google.android.libraries.**
-dontwarn org.maplibre.**
